let labIndex=0,labPositions=[0,0,0,0],labChoices=[null,null,null,null];
let quizFilter='all',quizSize='10',quizKind='situational',toastTimer;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=list=>{const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const includes=(arr,id)=>arr.includes(id);
const totalMastery=()=>Math.round(100*(state.read.length+state.known.length+state.solved.length)/(LESSONS.length+FLASHCARDS.length+QUESTIONS.length));
const xpTotal=()=>state.awards.reduce((n,key)=>n+(key.startsWith('lesson:')?25:key.startsWith('card:')?5:10),0);
function save(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;}updateChrome();}
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function updateChrome(){
  const percent=totalMastery();
  document.getElementById('mastery-side').textContent=percent+'%';
  const meter=document.getElementById('mastery-meter');meter.setAttribute('aria-valuenow',percent);meter.firstElementChild.style.width=percent+'%';
  document.getElementById('side-progress-detail').textContent=state.read.length+' of '+LESSONS.length+' lessons explored';
  document.getElementById('xp-value').textContent=xpTotal()+' XP';
  document.getElementById('save-status').textContent=storageOK?'Progress saves in this browser · No account needed':'Browser storage unavailable · Progress lasts for this visit';
  document.querySelectorAll('.nav [data-go]').forEach(el=>{if(el.dataset.go===view)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
  document.getElementById('breadcrumb').textContent={home:'Overview',learn:'Learn',cards:'Flashcards',lab:'Ward lab',quiz:'Quiz'}[view];
}
function grant(key,points){if(state.awards.includes(key))return 0;state.awards.push(key);return points;}
function toast(message){const el=document.getElementById('toast');clearTimeout(toastTimer);el.textContent=message;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,3500);}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=document.getElementById('confetti');el.innerHTML='';for(let i=0;i<35;i++){const bit=document.createElement('i');bit.style.left=Math.random()*100+'%';bit.style.background=['#b94722','#244e43','#ccab46','#b2c58f'][i%4];bit.style.animationDelay=Math.random()*.35+'s';bit.style.transform='rotate('+Math.random()*180+'deg)';el.appendChild(bit);}setTimeout(()=>el.innerHTML='',2200);}
const sourceRef=page=>'<span class="source-ref"><button data-action="source">Handout · p. '+page+'</button></span>';
const topicOptions=selected=>'<option value="all"'+(selected==='all'?' selected':'')+'>All topics</option>'+LESSONS.map((l,i)=>'<option value="'+i+'"'+(String(selected)===String(i)?' selected':'')+'>'+esc(l.tag)+'</option>').join('');
function pageTitle(eyebrow,title,description){return '<div class="page-title"><span class="eyebrow">'+eyebrow+'</span><h1>'+title+'</h1><p>'+description+'</p></div>';}
function buddySVG(){return `<svg viewBox="0 0 360 320" role="img" aria-label="Pip, a smiling clipboard study buddy with a nurse cap"><circle cx="182" cy="158" r="128" fill="#dae3c8"/><circle cx="182" cy="158" r="148" stroke="#bcc9aa" fill="none" stroke-dasharray="3 8"/><path d="m50 77 5 12 13 5-13 5-5 12-5-12-13-5 13-5Z" fill="#b94722"/><path d="m300 214 4 10 11 4-11 4-4 10-4-10-11-4 11-4Z" fill="#244e43"/><g transform="rotate(-8 180 160)"><path d="m125 242-11 25c-3 9 24 10 29 2l9-19m65-3 7 24c3 8 29 5 28-4l-13-27" fill="#244e43" stroke="#244e43" stroke-width="4" stroke-linecap="round"/><path d="M111 143c-40-1-38 48-59 36m190-38c38-15 39-44 53-43" fill="none" stroke="#244e43" stroke-width="12" stroke-linecap="round"/><rect x="106" y="61" width="146" height="192" rx="25" fill="#b94722" stroke="#244e43" stroke-width="3"/><rect x="117" y="72" width="124" height="165" rx="17" fill="#fffdf1"/><rect x="152" y="52" width="56" height="22" rx="7" fill="#244e43"/><path d="m144 61-8-29 85 2-10 29" fill="#fffdf1" stroke="#244e43" stroke-width="3"/><path d="M171 45h15m-7-7v15" stroke="#b94722" stroke-width="5" stroke-linecap="round"/><ellipse cx="153" cy="125" rx="5" ry="7" fill="#244e43"/><ellipse cx="205" cy="125" rx="5" ry="7" fill="#244e43"/><ellipse cx="140" cy="140" rx="10" ry="5" fill="#f5bea2"/><ellipse cx="217" cy="140" rx="10" ry="5" fill="#f5bea2"/><path d="M165 144q14 18 28-1" fill="none" stroke="#244e43" stroke-width="4" stroke-linecap="round"/><path d="m139 179 6 6 10-13m-15 31 6 6 10-13" fill="none" stroke="#244e43" stroke-width="3" stroke-linecap="round"/><path d="M168 179h44m-44 24h34" stroke="#b4c29f" stroke-width="5" stroke-linecap="round"/></g><g transform="rotate(9 292 62)"><rect x="262" y="36" width="66" height="43" rx="8" fill="#f6e6a7" stroke="#b6a05a"/><text x="295" y="63" text-anchor="middle" font-family="Segoe UI,Arial,sans-serif" font-size="16" font-weight="700" fill="#604c16">Aha!</text></g></svg>`;}
function renderHome(){
  const next=LESSONS.findIndex((_,i)=>!state.read.includes(i));
  const modes=[['learn','book','Learn the essentials','Bite-sized notes. Big-picture understanding.',LESSONS.length+' lessons · go at your pace'],['cards','cards','Make it stick','Think first. Flip. Build your recall.',FLASHCARDS.length+' flashcards · review your way'],['lab','flask','Try the ward lab','Spot the clues in real-world-style cases.','24 cases · 4 mini challenges'],['quiz','flag','Check your know-how','Test yourself, then learn from every answer.',QUESTIONS.length+' questions · no timer']];
  const badges=[['First steps',state.read.length>0],['Recall builder',state.known.length>=10],['Lab detective',state.labSolved.length>=12],['Quiz confident',state.quizBadge]];
  return `<div class="hello"><p><strong>Your next shift? In control.</strong><br><span class="muted">A fresh way to study nursing management.</span></p><span class="chip outline">3-page handout → one study adventure</span></div><section class="hero"><div><span class="chip peach">CHAPTER 05 · CONTROLLING</span><h1>A little practice.<br>A lot more <em>control.</em></h1><p>Meet the standards. Spot the gaps. Build the confidence to bring it all together.</p><button class="btn" data-action="continue">${next<0?'Put your knowledge to work':state.read.length?'Continue learning':'Let’s start learning'} ${icon('arrow')}</button><p class="small" style="margin:17px 0 0;font-size:12px">Learn → recall → apply → check yourself.</p></div><div class="hero-art">${buddySVG()}<span class="art-note">Pip says: you’ve got this.</span></div></section><div class="section-head"><div><h2>Find your study groove</h2><p>Follow the route, or jump into whatever you need.</p></div><span class="small muted">No timers. No pressure.</span></div><div class="mode-grid">${modes.map(m=>`<button class="mode-card" data-go="${m[0]}"><span class="mode-icon">${icon(m[1])}</span><span class="arrow">${icon('arrow')}</span><h3>${m[2]}</h3><p>${m[3]}</p><span class="mode-meta">${m[4]}</span></button>`).join('')}</div><div class="home-bottom"><section class="card"><div class="row between"><h2 style="font-size:22px;margin:0">Your learning route</h2><span class="chip outline">${state.read.length} / ${LESSONS.length} explored</span></div><div class="route-list" style="margin-top:17px">${LESSONS.map((l,i)=>`<button class="route-btn" data-lesson="${i}"><span class="route-num ${state.read.includes(i)?'done':''}">${state.read.includes(i)?icon('check'):String(i+1).padStart(2,'0')}</span><span class="route-title">${l.title}</span><span class="route-page">${l.minutes} min · p. ${l.page}</span>${icon('chevron')}</button>`).join('')}</div></section><div class="stack" style="align-content:start"><section class="card buddy-tip"><span class="eyebrow">Pip’s study tip</span><p class="quote">“If you can explain it without peeking, it’s starting to stick.”</p><p class="small">Try saying the answer out loud before you flip a flashcard. A little effort now makes your next review more useful.</p><button class="link-btn" data-go="cards">Give it a go ${icon('arrow')}</button></section><section class="card"><div class="row between"><h3 style="margin:0">Small wins count.</h3>${icon('cup')}</div><p class="small muted" style="margin:12px 0 0">${state.known.length} cards known · ${state.labSolved.length} cases solved<br>${state.lastQuiz?'Last quiz: '+state.lastQuiz.score+' / '+state.lastQuiz.total:'Your first quiz is waiting for you.'}</p><div class="badge-row">${badges.map(b=>`<span class="badge ${b[1]?'earned':''}" title="${b[1]?'Earned':'Keep going to unlock'}">${b[1]?'✓ ':'○ '}${b[0]}</span>`).join('')}</div><p class="small muted" style="margin:14px 0 0;font-size:11px">Unlock by: 1 lesson · 10 known cards · 12 cases · 80% on a quiz of 10+ questions.</p></section></div></div>`;
}
function renderLearn(){const l=LESSONS[lessonIndex],done=state.read.includes(lessonIndex);return pageTitle('01 / Learn','Little lessons. Lasting understanding.','Take one topic at a time. Pause at the recall check, then explain the idea in your own words.')+`<div class="learn-grid"><nav class="card lesson-menu" aria-label="Lessons">${LESSONS.map((item,i)=>`<button data-lesson="${i}" class="${i===lessonIndex?'active':''}" ${i===lessonIndex?'aria-current="step"':''}><span class="muted">${String(i+1).padStart(2,'0')}</span><span>${item.title}</span><span class="lesson-check" aria-label="${state.read.includes(i)?'Completed':'Not completed'}">${state.read.includes(i)?'✓':''}</span></button>`).join('')}</nav><article class="card lesson-article"><div class="row between wrap"><span class="chip">${l.tag}</span><span class="small muted">Lesson ${lessonIndex+1} / ${LESSONS.length} · ~${l.minutes} min</span></div><h2>${l.title}</h2><p class="muted">${l.lead}</p>${l.body}<details class="self-check"><summary>Pause & recall: ${l.check}</summary><p><strong>Check your thinking:</strong> ${l.answer}</p></details><details class="notes"><summary>Your own words · personal notes</summary><label for="lesson-note">What would you tell a classmate about this topic?</label><textarea id="lesson-note" data-note="${lessonIndex}" maxlength="15000" placeholder="Write a summary, an example, or a question to revisit…">${esc(state.notes[lessonIndex]||'')}</textarea><span class="small muted">Saved in this browser as you type when storage is available.</span></details><div class="lesson-footer">${sourceRef(l.page)}<div class="row wrap"><button class="btn secondary sm" data-action="lesson-cards">Practice this topic</button><button class="btn sm" data-action="complete-lesson">${done?(lessonIndex===LESSONS.length-1?'Finish with a quiz':'Next lesson'):'Got it · complete lesson'} ${icon(done?'arrow':'check')}</button></div></div></article></div>`;}
function currentCards(){let cards=FLASHCARDS.filter(c=>(cardFilter==='all'||c.lesson===+cardFilter)&&(!reviewOnly||!state.known.includes(c.id))&&(!cardSearch||(c.q+' '+c.a).toLowerCase().includes(cardSearch.toLowerCase())));if(cardOrder){const order=new Map(cardOrder.map((id,i)=>[id,i]));cards.sort((a,b)=>(order.get(a.id)??0)-(order.get(b.id)??0));}return cards;}
function renderCards(){
  const deck=currentCards();if(cardIndex>=deck.length)cardIndex=0;const c=deck[cardIndex];
  return pageTitle('02 / Recall','Flip a card. Find your aha.','Try to retrieve the answer before you reveal it. Mark what you know, and give tricky ideas another round.')+`<div class="toolbar"><div class="field"><label for="card-topic">Topic</label><select id="card-topic">${topicOptions(cardFilter)}</select></div><div class="field"><label for="card-search">Find a concept</label><input id="card-search" type="search" value="${esc(cardSearch)}" placeholder="Try ‘audit’ or ‘halo’"></div><label class="check-field"><input id="card-review" type="checkbox" ${reviewOnly?'checked':''}> Only cards still learning</label><button class="btn secondary sm" data-action="shuffle-cards">${icon('shuffle')} Shuffle</button></div><div class="flash-wrap">${c?`<div class="row between wrap" style="margin:25px 0 14px"><span class="chip">${LESSONS[c.lesson].tag}</span><span class="small muted">${state.known.length} / ${FLASHCARDS.length} known</span></div><button class="flashcard ${cardRevealed?'revealed':''}" data-action="flip-card" aria-label="${cardRevealed?'Answer: '+esc(c.a)+'. Activate to show question.':'Question: '+esc(c.q)+'. Activate to reveal answer.'}"><span class="eyebrow">${cardRevealed?'The answer':'Think it through'}</span><span class="${cardRevealed?'answer':'question'}">${esc(cardRevealed?c.a:c.q)}</span><span class="flip-hint">${cardRevealed?'Tap to see the question again':'Tap anywhere on the card to reveal'}</span></button><div class="flash-actions">${cardRevealed?`<button class="btn secondary" data-action="rate-learning">Keep practicing</button><button class="btn" data-action="rate-known">I know this ${icon('check')}</button>`:`<button class="btn" data-action="flip-card">Reveal answer ${icon('cards')}</button>`}</div><div class="flash-footer"><button class="btn ghost sm" data-action="prev-card" aria-label="Previous flashcard">${icon('left')} Previous</button><span>${cardIndex+1} / ${deck.length}${state.known.includes(c.id)?' · ✓ Known':''}</span><button class="btn ghost sm" data-action="next-card" aria-label="Next flashcard">Next ${icon('arrow')}</button></div><p class="keyboard-note">Space to flip · Arrow keys to browse · ${sourceRef(LESSONS[c.lesson].page)}</p>`:`<div class="empty"><h2>${reviewOnly&&!cardSearch?'A clear deck. Nice work!':'No matching cards'}</h2><p class="muted">${reviewOnly&&!cardSearch?'Everything in this selection is marked known. Revisit all cards any time.':'Try a different topic or search term.'}</p><button class="btn secondary" data-action="clear-card-filters">Show all flashcards</button></div>`}</div>`;
}
function renderLab(){
  const lab=LABS[labIndex],pos=labPositions[labIndex],c=lab.cases[pos],choice=labChoices[labIndex],answered=choice!==null,key=labIndex+'-'+pos,good=choice===c[2];
  return pageTitle('03 / Apply','Welcome to the ward lab.','Read the case, spot the clue, and make your call. Each mini challenge tackles a distinction that is easy to mix up.')+`<div class="tabs" role="group" aria-label="Choose a lab challenge">${LABS.map((l,i)=>`<button class="tab" data-lab="${i}" aria-pressed="${i===labIndex}">${l.title} <span class="small">${l.cases.filter((_,j)=>state.labSolved.includes(i+'-'+j)).length}/${l.cases.length}</span></button>`).join('')}</div><section class="case-panel card"><div class="row between wrap"><span class="chip">${lab.title}</span><span class="small muted">Case ${pos+1} / ${lab.cases.length}${state.labSolved.includes(key)?' · ✓ Solved':''}</span></div><div class="case-story"><span class="eyebrow">Ward file ${String(pos+1).padStart(2,'0')}</span><h2>${c[0]}</h2><p>${c[1]}</p></div><p><strong>${lab.prompt}</strong></p><div class="answer-grid">${lab.options.map((opt,i)=>`<button class="answer-btn ${answered&&i===c[2]?'correct':''} ${answered&&i===choice&&!good?'wrong':''}" data-lab-answer="${i}" ${answered?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${opt}</span>${answered&&i===c[2]?'<span class="mark">✓ Correct</span>':answered&&i===choice?'<span class="mark">× Your pick</span>':''}</button>`).join('')}</div>${answered?`<div class="feedback ${good?'':'wrong'}" tabindex="-1"><h3>${good?'Clue spotted. Nicely done!':'A useful mix-up to catch.'}</h3><p>${c[3]}</p>${sourceRef(LESSONS[lab.lesson].page)}</div><div class="row between wrap"><button class="btn secondary sm" data-lesson="${lab.lesson}">Review the concept</button><button class="btn" data-action="next-case">${pos===lab.cases.length-1?'Round complete · go again':'Next case'} ${icon('arrow')}</button></div>`:`<p class="small muted" style="margin:20px 0 0">First correct solve earns 10 XP. A repeat lets you practice without adding points.</p>`}</section>`;
}
function availableQuestions(){return QUESTIONS.filter(q=>(quizFilter==='all'||q.lesson===+quizFilter)&&(quizKind==='all'||(quizKind==='situational'?q.situational:!q.situational)));}
function scenarioBanner(){return `<section class="card scenario-banner" aria-label="New situational questions"><div><span class="chip outline">NEW · ${SCENARIOS.length} SITUATIONAL QUESTIONS</span><h2>A shift full of decisions.</h2><p>Dialysis, NICU, PACU, oncology, and more. Read a specific situation, make your call, then unpack the clues behind every choice.</p><p class="scenario-progress">${state.solved.filter(id=>QUESTIONS[id]?.situational).length} / ${SCENARIOS.length} cases answered correctly · 3 cases per lesson</p></div><button class="btn" data-action="start-situational">Try a situational round ${icon('arrow')}</button></section>`;}
function scenarioStory(q){return q.situational?`<section class="case-story scenario-story" aria-label="Situation"><span class="eyebrow">Situation · ${esc(q.unit)}</span><h2 style="font-size:24px;margin:12px 0">${esc(q.title)}</h2><p>${esc(q.story)}</p></section>`:'';}
function scenarioFeedback(q,order){return q.situational?`<div class="scenario-feedback"><p><strong>Deciding clue:</strong> ${esc(q.clue)}</p><details class="distractor-review"><summary>Why the other options don’t fit</summary><ul>${order.filter(i=>i!==q.correct).map(i=>`<li><strong>${esc(q.options[i])}:</strong> ${esc(q.rationale[i])}</li>`).join('')}</ul></details></div>`:'';}
function renderQuizSetup(){
 const count=availableQuestions().length,scenariosSolved=state.solved.filter(id=>QUESTIONS[id]?.situational).length;
 const kinds=[['situational','Situational cases only · '+SCENARIOS.length],['core','Core concepts · '+SCENARIO_ID_START],['all','Mix everything · '+QUESTIONS.length]];
 return pageTitle('04 / Check yourself','Your next shift starts with a question.','Try specific nursing-management situations, review the fundamentals, or mix both. There is no timer.')+`<section class="card quiz-card"><span class="chip peach">${SCENARIOS.length} new situations · 3 per lesson</span><h2 style="margin:20px 0 12px">Build your quiz</h2><p class="muted">The situational round brings you into NICU handovers, dialysis service planning, recovery-room audits, and other specific settings. After answering, check the deciding clue and explanations of the other options.</p><div class="toolbar"><div class="field"><label for="quiz-kind">Question style</label><select id="quiz-kind">${kinds.map(k=>`<option value="${k[0]}" ${quizKind===k[0]?'selected':''}>${k[1]}</option>`).join('')}</select></div><div class="field"><label for="quiz-topic">Topic</label><select id="quiz-topic">${topicOptions(quizFilter)}</select></div><div class="field"><label for="quiz-size">Quiz length</label><select id="quiz-size"><option value="10" ${quizSize==='10'?'selected':''}>Quick practice · up to 10</option><option value="all" ${quizSize==='all'?'selected':''}>Full selection · ${count}</option></select></div></div><p class="small muted">${Math.min(count,quizSize==='all'?count:10)} questions in this selection · Choices shuffle each round.</p><button class="btn" data-action="start-quiz">Start quiz ${icon('arrow')}</button><p class="scenario-progress">Situational progress: ${scenariosSolved} / ${SCENARIOS.length} answered correctly.</p><hr class="divider"><div class="row between wrap"><div><h3 style="font-size:18px;margin:0 0 7px">Give tricky questions a second look.</h3><p class="small muted" style="margin:0">${state.missed.length} question${state.missed.length===1?'':'s'} in your review pile, across all question styles.</p></div><button class="btn secondary sm" data-action="review-missed" ${state.missed.length?'':'disabled'}>Review missed</button></div>${state.lastQuiz?`<div class="callout" style="margin-bottom:0"><strong>Last quiz: ${state.lastQuiz.score} / ${state.lastQuiz.total}</strong><p>Your next attempt is another chance to learn.</p></div>`:''}</section>`;
}
function quizScore(s){return s.answers.reduce((n,a,i)=>n+(a===QUESTIONS[s.items[i].id].correct?1:0),0);}
function renderQuiz(){
 const s=state.session;if(!s)return renderQuizSetup();if(s.done)return renderResults();
 const item=s.items[s.pos],q=QUESTIONS[item.id],answer=s.answers[s.pos],answered=answer!==null,good=answer===q.correct,completed=s.answers.filter(a=>a!==null).length;
 return pageTitle('04 / Check yourself',s.review?'A second look. A stronger memory.':q.situational?'You’re in charge. Read the situation.':'One good question at a time.',q.situational?'Look for the management decision, the timing, or the audit lens being asked about. Choose the single best answer.':'Choose an answer, then use the explanation to check your reasoning.')+`<section class="card quiz-card"><div class="row between wrap"><div class="row wrap"><span class="chip">${LESSONS[q.lesson].tag}</span>${q.situational?'<span class="chip peach">Situational</span>':''}</div><button class="btn ghost sm" data-action="quiz-setup">Change quiz</button></div><div class="quiz-status"><span>Question ${s.pos+1} of ${s.items.length}</span><span>${quizScore(s)} correct · ${s.items.length-completed} unanswered</span></div><div class="meter" role="progressbar" aria-label="Quiz completion" aria-valuemin="0" aria-valuemax="${s.items.length}" aria-valuenow="${completed}"><span style="width:${100*completed/s.items.length}%"></span></div>${scenarioStory(q)}<h2 class="question-text">${q.q}</h2><div class="quiz-options">${item.order.map((original,i)=>`<button class="answer-btn ${answered&&original===q.correct?'correct':''} ${answered&&original===answer&&!good?'wrong':''}" data-quiz-answer="${original}" ${answered?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${q.options[original]}</span>${answered&&original===q.correct?'<span class="mark">✓ Correct</span>':answered&&original===answer?'<span class="mark">× Your pick</span>':''}</button>`).join('')}</div>${answered?`<div class="feedback ${good?'':'wrong'}" tabindex="-1"><h3>${good?'That’s it. You’ve got the idea.':'Keep this clue for next time.'}</h3><p>${q.why}</p>${scenarioFeedback(q,item.order)}${sourceRef(LESSONS[q.lesson].page)}</div><div class="row between wrap"><button class="btn secondary sm" data-lesson="${q.lesson}">Revisit lesson</button><button class="btn" data-action="next-question">${s.pos===s.items.length-1?'See my results':'Next question'} ${icon('arrow')}</button></div>`:`<p class="small muted" style="margin:20px 0 0">${q.situational?'An original practice case based on the handout’s management concepts.':'Take your time. Think about the defining clue.'}</p>`}</section>`;
}
function renderResults(){
 const s=state.session,score=quizScore(s),pct=Math.round(100*score/s.items.length),wrong=s.items.filter((it,i)=>s.answers[i]!==QUESTIONS[it.id].correct);
 return pageTitle('04 / Your results','Every attempt moves you forward.','Use your results to choose what to revisit. You can open a lesson at any time and return to these results.')+`<section class="card quiz-card"><div class="results"><span class="chip yellow">${pct>=80?'A strong round!':pct>=50?'You’re building the connections.':'A fresh starting point.'}</span><div class="score-ring" style="--pct:${pct}%"><strong>${pct}%</strong></div><h2>${score} out of ${s.items.length} correct</h2><p class="muted">${wrong.length?wrong.length+' question'+(wrong.length===1?' needs':'s need')+' another look. That’s your next study focus.':'You got every question in this round. Keep the ideas fresh with a later review.'}</p><div class="row wrap" style="justify-content:center">${wrong.length?`<button class="btn" data-action="retry-round">Retry these ${wrong.length} ${icon('arrow')}</button>`:''}<button class="btn ${wrong.length?'secondary':''}" data-action="quiz-setup">Build another quiz</button><button class="btn ghost" data-go="home">Back to overview</button></div></div><h3 style="font-size:20px">Your answer review</h3><p class="small muted">Open a question to revisit its situation, your answer, the deciding clue, and the alternatives.</p><div class="result-review">${s.items.map((it,i)=>{const q=QUESTIONS[it.id],a=s.answers[i],correct=a===q.correct;return `<details><summary>${correct?'✓':'×'} ${i+1}. ${q.situational?esc(q.unit)+' · '+esc(q.title)+' — ':''}${q.q}</summary>${scenarioStory(q)}<p><strong>Your answer:</strong> ${q.options[a]}</p>${correct?'':`<p><strong>Correct answer:</strong> ${q.options[q.correct]}</p>`}<p>${q.why}</p>${scenarioFeedback(q,it.order)}<button class="link-btn" data-lesson="${q.lesson}">Review: ${LESSONS[q.lesson].title}</button> ${sourceRef(LESSONS[q.lesson].page)}</details>`;}).join('')}</div></section>`;
}
function render(){const main=document.getElementById('main');main.innerHTML=({home:renderHome,learn:renderLearn,cards:renderCards,lab:renderLab,quiz:renderQuiz}[view]||renderHome)();if(view==='home')main.querySelector('.hero').insertAdjacentHTML('afterend',scenarioBanner());hydrate(main);updateChrome();}
function go(target,lesson){const hash=target==='learn'?'#learn/'+(lesson??lessonIndex):'#'+target;if(location.hash===hash){readRoute();return;}location.hash=hash;}
function readRoute(){const parts=location.hash.slice(1).split('/');view=['home','learn','cards','lab','quiz'].includes(parts[0])?parts[0]:'home';if(view==='learn'){const n=Number(parts[1]??0);lessonIndex=Number.isInteger(n)&&n>=0&&n<LESSONS.length?n:0;}render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});}
function focusFeedback(){const el=document.querySelector('#main .feedback');if(el)el.focus({preventScroll:true});}
function advanceCard(delta){const deck=currentCards();if(!deck.length)return;cardIndex=(cardIndex+delta+deck.length)%deck.length;cardRevealed=false;render();document.querySelector('.flashcard')?.focus({preventScroll:true});}
function startQuiz(ids,review=false){if(!ids.length){toast('No questions to review yet. Try a practice quiz.');return;}const items=shuffle(ids).map(id=>({id,order:shuffle(QUESTIONS[id].options.map((_,i)=>i))}));state.session={items,answers:items.map(()=>null),pos:0,done:false,review};save();if(view==='quiz'){render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});}else go('quiz');}
function setCardTopic(topic){cardFilter=String(topic);cardSearch='';cardIndex=0;cardOrder=null;cardRevealed=false;reviewOnly=false;go('cards');}
function buildPrint(){document.getElementById('print-sheet').innerHTML='<h1>Control Quest · Study notes</h1><p>NCM 433 · Controlling · Based on 5. Controlling (1).pdf, pp. 1–3.<br>Source: Joel Boniao | BSN4-N4. Memory hooks and practice prompts created for this study guide.</p>'+LESSONS.map((l,i)=>'<article><h2>'+String(i+1).padStart(2,'0')+'. '+l.title+'</h2><p><strong>'+l.lead+'</strong> (Handout p. '+l.page+')</p>'+l.body+(state.notes[i]?'<h3>My notes</h3><p style="white-space:pre-wrap">'+esc(state.notes[i])+'</p>':'')+'</article>').join('');}
function openSource(){document.getElementById('source-dialog').showModal();}
const ACTIONS={
  source:openSource,
  'close-source':()=>document.getElementById('source-dialog').close(),
  continue:()=>{const i=LESSONS.findIndex((_,n)=>!state.read.includes(n));if(i<0)go('quiz');else go('learn',i);},
  'complete-lesson':()=>{if(state.read.includes(lessonIndex)){if(lessonIndex===LESSONS.length-1)go('quiz');else go('learn',lessonIndex+1);return;}state.read.push(lessonIndex);const earned=grant('lesson:'+lessonIndex,25);save();render();toast('Lesson complete'+(earned?' · +25 XP':'')+' · Take a breath, then keep going.');if(state.read.length===LESSONS.length)celebrate();},
  'lesson-cards':()=>setCardTopic(lessonIndex),
  'flip-card':()=>{if(!currentCards().length)return;cardRevealed=!cardRevealed;render();document.querySelector('.flashcard')?.focus({preventScroll:true});},
  'next-card':()=>advanceCard(1),
  'prev-card':()=>advanceCard(-1),
  'shuffle-cards':()=>{cardOrder=shuffle(FLASHCARDS.map(c=>c.id));cardIndex=0;cardRevealed=false;render();toast('Fresh order. Fresh perspective.');},
  'clear-card-filters':()=>{cardFilter='all';cardSearch='';reviewOnly=false;cardIndex=0;cardRevealed=false;render();},
  'rate-known':()=>{const c=currentCards()[cardIndex];if(!c||!cardRevealed)return;if(!state.known.includes(c.id))state.known.push(c.id);const earned=grant('card:'+c.id,5);save();if(reviewOnly){cardRevealed=false;if(cardIndex>=currentCards().length)cardIndex=0;render();document.querySelector('.flashcard')?.focus({preventScroll:true});}else advanceCard(1);toast('Marked known'+(earned?' · +5 XP':'')+' · Revisit it later to keep it fresh.');},
  'rate-learning':()=>{const c=currentCards()[cardIndex];if(!c||!cardRevealed)return;state.known=state.known.filter(id=>id!==c.id);save();advanceCard(1);toast('Kept in your practice pile. You’re learning.');},
  'next-case':()=>{const last=labPositions[labIndex]===LABS[labIndex].cases.length-1;labPositions[labIndex]=(labPositions[labIndex]+1)%LABS[labIndex].cases.length;labChoices[labIndex]=null;render();if(last){toast('Round complete. Try another lab or have another go.');celebrate();}},
  'start-quiz':()=>{const pool=availableQuestions().map(q=>q.id);startQuiz(shuffle(pool).slice(0,quizSize==='all'?pool.length:10));},
  'start-situational':()=>{quizKind='situational';quizFilter='all';quizSize='10';startQuiz(shuffle(QUESTIONS.filter(q=>q.situational).map(q=>q.id)).slice(0,10));},
  'review-missed':()=>startQuiz([...state.missed],true),
  'retry-round':()=>{const s=state.session;if(s)startQuiz(s.items.filter((it,i)=>s.answers[i]!==QUESTIONS[it.id].correct).map(it=>it.id),true);},
  'quiz-setup':()=>{state.session=null;save();render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});},
  'next-question':()=>{const s=state.session;if(!s||s.answers[s.pos]===null||s.done)return;if(s.pos<s.items.length-1)s.pos++;else{if(s.answers.some(a=>a===null))return;s.done=true;const score=quizScore(s);if(!s.review)state.lastQuiz={score,total:s.items.length};if(s.items.length>=10&&score/s.items.length>=.8)state.quizBadge=true;if(score/s.items.length>=.8)celebrate();}save();render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});},
  print:()=>{buildPrint();window.print();},
  reset:()=>{if(!confirm('Reset all Control Quest progress, XP, quiz history, and personal notes in this browser? This cannot be undone.'))return;state=freshState();cardIndex=0;cardRevealed=false;cardFilter='all';cardSearch='';reviewOnly=false;cardOrder=null;labPositions=[0,0,0,0];labChoices=[null,null,null,null];save();go('home');toast('A fresh start. Your study room is ready.');}
};
document.addEventListener('click',event=>{
  const btn=event.target.closest('button,[data-action]');if(!btn||btn.disabled)return;
  if(btn.dataset.go){go(btn.dataset.go);return;}
  if(btn.dataset.lesson!==undefined){const n=+btn.dataset.lesson;if(LESSONS[n])go('learn',n);return;}
  if(btn.dataset.lab!==undefined){labIndex=+btn.dataset.lab;render();return;}
  if(btn.dataset.labAnswer!==undefined){const lab=LABS[labIndex],pos=labPositions[labIndex];if(labChoices[labIndex]!==null)return;const answer=+btn.dataset.labAnswer;labChoices[labIndex]=answer;if(answer===lab.cases[pos][2]){const key=labIndex+'-'+pos;if(!state.labSolved.includes(key))state.labSolved.push(key);const earned=grant('lab:'+key,10);save();if(earned)toast('Case solved · +10 XP');}render();focusFeedback();return;}
  if(btn.dataset.quizAnswer!==undefined){const s=state.session;if(!s||s.done||s.answers[s.pos]!==null)return;const answer=+btn.dataset.quizAnswer,q=QUESTIONS[s.items[s.pos].id];s.answers[s.pos]=answer;if(answer===q.correct){if(!state.solved.includes(q.id))state.solved.push(q.id);state.missed=state.missed.filter(id=>id!==q.id);const earned=grant('quiz:'+q.id,10);if(earned)toast('Connection made · +10 XP');}else if(!state.missed.includes(q.id))state.missed.push(q.id);save();render();focusFeedback();return;}
  if(btn.dataset.action&&ACTIONS[btn.dataset.action])ACTIONS[btn.dataset.action]();
});
document.addEventListener('change',event=>{
  const el=event.target;
  if(el.id==='card-topic'){cardFilter=el.value;cardIndex=0;cardRevealed=false;render();document.getElementById('card-topic').focus({preventScroll:true});}
  if(el.id==='card-review'){reviewOnly=el.checked;cardIndex=0;cardRevealed=false;render();document.getElementById('card-review').focus({preventScroll:true});}
  if(el.id==='quiz-topic'){quizFilter=el.value;render();document.getElementById('quiz-topic').focus({preventScroll:true});}
  if(el.id==='quiz-size'){quizSize=el.value;render();document.getElementById('quiz-size').focus({preventScroll:true});}
  if(el.id==='quiz-kind'){quizKind=el.value;render();document.getElementById('quiz-kind').focus({preventScroll:true});}
});
document.addEventListener('input',event=>{
  const el=event.target;
  if(el.id==='card-search'){cardSearch=el.value;cardIndex=0;cardRevealed=false;const pos=el.selectionStart;render();const next=document.getElementById('card-search');next.focus({preventScroll:true});try{next.setSelectionRange(pos,pos);}catch(e){}}
  if(el.dataset.note!==undefined){state.notes[el.dataset.note]=el.value;save();}
});
document.addEventListener('keydown',event=>{
  if(view!=='cards'||document.getElementById('source-dialog').open||event.ctrlKey||event.metaKey||event.altKey||event.shiftKey)return;
  const target=event.target;if(target.closest('input,textarea,select,[contenteditable="true"]'))return;
  if(event.key==='ArrowRight'){event.preventDefault();advanceCard(1);}
  if(event.key==='ArrowLeft'){event.preventDefault();advanceCard(-1);}
  if(event.code==='Space'&&(!target.closest('button,a')||target.closest('.flashcard'))){event.preventDefault();ACTIONS['flip-card']();}
});
window.addEventListener('hashchange',readRoute);
window.addEventListener('beforeprint',buildPrint);
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();document.getElementById('main').focus();});
document.getElementById('source-dialog').addEventListener('click',event=>{if(event.target===event.currentTarget){const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.currentTarget.close();}});
document.getElementById('download-source').href='data:application/pdf;base64,'+PDF_BASE64;
hydrate();readRoute();save();
